+BacklightBrightness::~BacklightBrightness() = default;
+
 bool BacklightBrightness::isSupported() const
 {
     return m_maxBrightness > 0;
 }

+void BacklightBrightness::applySettings()
+{
+    m_perceptual = m_settings->perceptualBrightness();
+    m_minRawBrightness = std::clamp(m_settings->minimumBrightness(), 0, m_maxBrightness - 1);
+    qCDebug(POWERDEVIL) << "[BacklightBrightness]: Using" << (m_perceptual ? "perceptual" : "linear") << "scale with minimum raw brightness"
+                        << m_minRawBrightness << "for" << m_syspath;
+}
+
+// Brightness 1 (the lowest still-visible level) maps to the minimum raw brightness, the maximum maps to the maximum.
+// The perceptual scale approximates CIE L* lightness, see DOI 10.1002/col.21768. The default (linear, minimum 1) is
+// the identity mapping.
+static constexpr double s_lightnessExponent = 0.42;
+
+int BacklightBrightness::toRawBrightness(int brightness) const
+{
+    if (!m_settings) {
+        return brightness;
+    }
+    if (brightness < 1) {
+        return std::min(brightness, m_minRawBrightness);
+    }
+    double ratio = (brightness - 1) / double(m_maxBrightness - 1);
+    if (m_perceptual) {
+        ratio = std::pow(ratio, 1.0 / s_lightnessExponent);
+    }
+    return m_minRawBrightness + std::lround(ratio * (m_maxBrightness - m_minRawBrightness));
+}
+
+int BacklightBrightness::fromRawBrightness(int rawBrightness) const
+{
+    if (!m_settings || rawBrightness < 1) {
+        return rawBrightness;
+    }
+    if (rawBrightness <= m_minRawBrightness) {
+        return 1;
+    }
+    double ratio = (rawBrightness - m_minRawBrightness) / double(m_maxBrightness - m_minRawBrightness);
+    if (m_perceptual) {
+        ratio = std::pow(ratio, s_lightnessExponent);
+    }
+    return 1 + std::lround(ratio * (m_maxBrightness - 1));
+}
