     KAuth::Action action(u"org.kde.powerdevil.backlighthelper.setbrightness"_s);
     action.setHelperId(HELPER_ID);
-    action.addArgument(u"brightness"_s, newBrightness);
+    action.addArgument(u"brightness"_s, newRawBrightness);
     auto *job = action.execute();

     connect(job, &KAuth::ExecuteJob::result, this, [this, job] {
@@ -253,11 +320,11 @@ void BacklightBrightness::setBrightness(int newBrightness)

         if (job->error()) {
             qCWarning(POWERDEVIL) << "[BacklightBrightness]: Failed to set screen brightness" << job->error() << job->errorText();
-            Q_EMIT externalBrightnessChangeObserved(this, m_observedBrightness);
+            Q_EMIT externalBrightnessChangeObserved(this, fromRawBrightness(m_observedBrightness));
