+void PowerKCM::detectBacklight()
+{
+    // Ask the same helper as the daemon, so that settings are stored for the backlight device it actually uses
+    KAuth::Action syspathAction(u"org.kde.powerdevil.backlighthelper.syspath"_s);
+    syspathAction.setHelperId(u"org.kde.powerdevil.backlighthelper"_s);
+    KAuth::ExecuteJob *syspathJob = syspathAction.execute();
+    connect(syspathJob, &KJob::result, this, [this, syspathJob] {
+        const QString deviceName = QFileInfo(syspathJob->data()[u"syspath"_s].toString()).fileName();
+        if (syspathJob->error() || deviceName.isEmpty()) {
+            return;
+        }
+        KAuth::Action brightnessMaxAction(u"org.kde.powerdevil.backlighthelper.brightnessmax"_s);
+        brightnessMaxAction.setHelperId(u"org.kde.powerdevil.backlighthelper"_s);
+        KAuth::ExecuteJob *brightnessMaxJob = brightnessMaxAction.execute();
+        connect(brightnessMaxJob, &KJob::result, this, [this, brightnessMaxJob, deviceName] {
+            const int maxBrightness = brightnessMaxJob->data()[u"brightnessmax"_s].toInt();
+            if (brightnessMaxJob->error() || maxBrightness < 2) {
+                return;
+            }
+            m_backlightMaxBrightness = maxBrightness;
+            m_backlightSettings = new BacklightSettings(deviceName, this);
+            m_backlightSettings->load();
+            registerSettings(m_backlightSettings);
+            Q_EMIT backlightSettingsChanged();
+        });
+        brightnessMaxJob->start();
+    });
+    syspathJob->start();
+}
